// The MediaPipe canonical face mesh (468 vertices) with derived tables. Generated by
// facet/scripts/build_canonical.py; the Python metrics library reads the same file.
import raw from "./canonical.json";

export type Vec3 = [number, number, number];

export interface Canonical {
  vertices: Vec3[];
  faces: [number, number, number][];
  midline: number[];
  pairs: [number, number, string][];
  rigid: number[];
  zones: Record<string, number[]>;
}

export const canonical = raw as unknown as Canonical;

export const MESH_VERTICES = 468;
export const MESH_VERTICES_WITH_IRIS = 478;

/** Unique mesh edges, for drawing the wireframe. */
export const EDGES: [number, number][] = (() => {
  const seen = new Set<number>();
  const edges: [number, number][] = [];
  for (const [a, b, c] of canonical.faces) {
    for (const [i, j] of [
      [a, b],
      [b, c],
      [c, a],
    ] as const) {
      const key = i < j ? i * 1000 + j : j * 1000 + i;
      if (!seen.has(key)) {
        seen.add(key);
        edges.push([i, j]);
      }
    }
  }
  return edges;
})();

